```python
async def serialize_response(
    *,
    field: ModelField = None,
    response_content: Any,
    include: Union[SetIntStr, DictIntStrAny] = None,
    exclude: Union[SetIntStr, DictIntStrAny] = set(),
    by_alias: bool = True,
    exclude_unset: bool = False,
    is_coroutine: bool = True,
) -> Any:
    if field:
        errors = []
        if exclude_unset and isinstance(response_content, BaseModel):
            if PYDANTIC_1:
                response_content = response_content.dict(exclude_unset=exclude_unset)
            else:
                response_content = response_content.dict(
                    skip_defaults=exclude_unset
                )  # pragma: nocover
        if is_coroutine:
            value, errors_ = field.validate(response_content, {}, loc=("response",))
        else:
            value, errors_ = await run_in_threadpool(
                field.validate, response_content, {}, loc=("response",)
            )
        if isinstance(errors_, ErrorWrapper):
            errors.append(errors_)
        elif isinstance(errors_, list):
            errors.extend(errors_)
        if errors:
            # If validation fails, try to validate each field individually
            # to give more informative error messages
            if isinstance(response_content, dict):
                for key, value in response_content.items():
                    if key in field.type_.dict():
                        field_name = field.type_.dict()[key]
                        if field_name.alias in field.type_.__fields__:
                            field_to_validate = field.type_.__fields__[field_name.alias]
                            try:
                                field_to_validate.validate(value, {}, loc=(key,))
                            except ValidationError as e:
                                errors.extend(e.errors())
                        else:
                            errors.append(
                                ErrorWrapper(
                                    ValidationError(
                                        [ErrorWrapperexc.DataError("Invalid field name")], field
                                    ),
                                    loc=key,
                                )
                            )
            raise ValidationError(errors, field.type_)
        if by_alias:
            return jsonable_encoder(
                value, include=include, exclude=exclude, by_alias=True, exclude_unset=exclude_unset
            )
        else:
            return jsonable_encoder(
                value, include=include, exclude=exclude, by_alias=False, exclude_unset=exclude_unset
            )
    else:
        if by_alias:
            return jsonable_encoder(response_content, include=include, exclude=exclude, by_alias=True)
        else:
            return jsonable_encoder(response_content, include=include, exclude=exclude, by_alias=False)
```
